catalog_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   g_form.setValue('current_section', '1');
   var fieldsToShow = ['geo', 'country', 'company'];
   var fieldsToHide = ['step2_variables', 'step3_variables', 'step4_variables', 'requested_by', 'alternate_buyer', 'first_payment_approver_dispaly'];

   for (var i = 0; i < fieldsToShow.length; i++) {
	g_form.setDisplay(fieldsToShow[i], true);
   }

   for (var j = 0; j < fieldsToHide.length; j++) {
	g_form.setDisplay(fieldsToHide[j], false);
   }

   g_form.setMandatory('alternate_buyer', false);
   g_form.setMandatory('first_payment_approver_dispaly', false);
   g_form.setDisplay('alternate_buyer', false, true);
   g_form.setDisplay('first_payment_approver_dispaly', false, true);
}
